import { validateEntry } from "./validateEntry";

describe("validateEntry", () => {
    test("accepts valid entry with name and message", () => {
        const result = validateEntry("Alice", "Hello, world!");
        expect(result.ok).toBe(true);
        expect(result.error).toBeUndefined();
    });

    test("rejects entry with empty name", () => {
        const result = validateEntry("", "Message");
        expect(result.ok).toBe(false);
        expect(result.error).toBe("Name must be between 1 and 40 characters");
    });

    test("rejects entry with name longer than 40 characters", () => {
        const longName = "A".repeat(41);
        const result = validateEntry(longName, "Message");
        expect(result.ok).toBe(false);
        expect(result.error).toBe("Name must be between 1 and 40 characters");
    });

    test("rejects entry with empty message", () => {
        const result = validateEntry("Bob", "");
        expect(result.ok).toBe(false);
        expect(result.error).toBe("Message must be between 1 and 200 characters");
    });

    test("rejects entry with message longer than 200 characters", () => {
        const longMsg = "A".repeat(201);
        const result = validateEntry("Charlie", longMsg);
        expect(result.ok).toBe(false);
        expect(result.error).toBe("Message must be between 1 and 200 characters");
    });

    test("accepts entry with exactly 40 character name", () => {
        const result = validateEntry("A".repeat(40), "Test message");
        expect(result.ok).toBe(true);
    });

    test("accepts entry with exactly 200 character message", () => {
        const longMsg = "B".repeat(200);
        const result = validateEntry("Test", longMsg);
        expect(result.ok).toBe(true);
    });
});

